schema_ddl:
CREATE TABLE EMPLOYEE (
    EMPLOYEE_ID INT,
    NAME VARCHAR(255),
    EXPERIENCE_YEARS INT,
    PRIMARY KEY (EMPLOYEE_ID),
    CHECK (EXPERIENCE_YEARS >= 0)
);
CREATE TABLE PROJECT (
    PROJECT_ID INT,
    EMPLOYEE_ID INT,
    PRIMARY KEY (PROJECT_ID, EMPLOYEE_ID),
    FOREIGN KEY (EMPLOYEE_ID) REFERENCES EMPLOYEE(EMPLOYEE_ID)
);

